1	// The executor (tasks-dispatch DESIGN §6) — a pull worker over the queue. Each
2	// iteration: pick the next ready item, claim it by a verified lease, re-evaluate
3	// the precondition (the scheduler run asked once at the anchor; a chained stage
4	// re-derives world state rather than trusting a verdict passed forward), then on
5	// a go run code-work and either converge (agentless) or hand off to an agent
6	// session; on a no-go close the item with the reason on record — the next
7	// occurrence is the scheduler run's ask at the task's next anchor (#1115).
8	//
9	// An executor's whole interface is issue read/write plus the repo at HEAD, which
10	// is what makes it platform-agnostic: the reference deployment is a job in the
11	// vendored workflows (the scheduler run's post-scheduler run drain, and a `labeled`-event run for
12	// latency), but a runner anywhere with an issues-scope token qualifies. Nothing
13	// enumerates executors; identity is self-declared in the claim comment.
14	//
15	// The pure decisions live at the top and test with fixtures; the shell below is
16	// the GitHub/code-work/invocation I/O around them.
17	
18	import { existsSync } from 'node:fs';
19	import { pathToFileURL } from 'node:url';
20	import { isSuspended, liveSuspendReader, suspendedNotice, SUSPEND_ALL_VAR } from './suspend.mjs';
21	import { HEARTBEAT_MS, heartbeatComment, withHeartbeat } from './heartbeat.mjs';
22	import { renderTaskExec } from '../run-record.mjs';
23	import { evaluatePreconditions } from '../precondition-policy.mjs';
24	import { windowDaysOf } from './signals.mjs';
25	import { isScheduledTask } from '../task-contract.mjs';
26	import { swapStatus, clearStatus } from './apply-status.mjs';
27	import { resolveTarget, closeSuperseded } from './target.mjs';
28	import { deliveryFor } from '../land-pr.mjs';
29	import {
30	  BLOCKED, READY, URGENT, EXECUTING, AGENT, requeueHint,
31	  STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT, isStatus,
32	  TASK_DONE, TASK_OBSOLETE, QUEUE_LABELS, QUEUED_LABEL, isStandingItem,
33	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_FAILURE,
34	  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
35	  parseWorkItemTitle, parseWorkItemBody, taskIdFromPath, parseContextLines, mergeContext, withNotBefore, withSection, editItemBody, hasLabel, DELIVERED_HEADING, LEGACY_DELIVERED_HEADINGS,
36	  LAST_VERDICT_HEADING, lastVerdictLines,
37	  withTarget,
38	  itemFacts,
39	} from './work-item.mjs';
40	
41	const titleOf = (item) => (item.title ?? '').trim();
42	// An item somebody is executing — the executor holds it, or the agent it handed to
43	// does. Decoded, never a literal label test: the item may wear any engine's spelling.
44	const running = (item) => isStatus(item, STATUS_RUNNING_EXECUTOR) || isStatus(item, STATUS_RUNNING_AGENT);
45	// WHICH TASK AN ITEM NAMES. A filed `[claudinite-work]` item says so in its title;
46	// a marked issue (DESIGN §16.1) keeps its own human title and names its task in the
47	// machine block's first line, so the id comes from the task whose worker path that
48	// is. `pathTo` is that lookup, injected because only the run holds the task set.
49	const taskIdOf = (item, pathTo = () => null) => {
50	  const p = parseWorkItemTitle(item.title);
51	  if (p) return `${p.pack}/${p.task}`;
52	  return pathTo(parseWorkItemBody(item.body).taskPath) ?? null;
53	};
54	
55	// The pick order (DESIGN §6.1): urgent first, then RANDOM among the ready, with
56	// two skip rules read live at pick time. Random rather than oldest-first because
57	// nothing leans on FIFO aging — the stale-ready escalation is period-scale — while
58	// a deterministic order lets one unlucky head dominate every run of a chain
59	// (DESIGN §15.20).
60	//
61	//  - SAME-TITLE MUTEX (S15/F6): skip an item whose exact title has another open
62	//    item executing or handed to an agent — one task, one execution at a time,
63	//    while a fan-out's distinct qualifiers still parallelize.
64	//  - THE `after` YIELD (S23): skip a scheduled item whose task declares `after:
65	//    [T]` while T's standing item is live THIS CYCLE (ready / executing / agent).
66	//    A declined upstream holds nothing back — it has no item at all (a no files
67	//    nothing, DESIGN §5) — and neither does one sitting `needs-human`: a broken
68	//    upstream must not halt its dependents indefinitely.
69	//
70	// `open` is every open work item; `taskAfter(id)` gives a task's declared
71	// upstreams as `<pack>/<task>` ids, and `scheduledOf(id)` whether that task is
72	// asked by the scheduler at HEAD (`isScheduledTask`; null where the repo no longer
73	// carries it) — which is half of what says whether an item is a standing
74	// occurrence or an ad-hoc run (§15.26). `random` is the tie-break draw, injected
75	// so a test can pin an order the production call deliberately does not have.
76	export function pickOrder(open = [], { taskAfter = () => [], scheduledOf = () => null, random = Math.random, pathTo = () => null } = {}) {
77	  const idOf = (item) => taskIdOf(item, pathTo);
78	  const live = (item) => [STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT].some((s) => isStatus(item, s));
79	  const standing = (item) => isStandingItem(item, scheduledOf(idOf(item)));
80	  const liveUpstream = (upstreamId) => open.some((o) =>
81	    idOf(o) === upstreamId && standing(o) && live(o));
82	  // One draw per item, taken once: a comparator that called `random()` per
83	  // comparison would not be a consistent ordering, and `Array.sort` on one is
84	  // free to produce anything at all.
85	  const draw = new Map(open.map((i) => [i.number, random()]));
86	
87	  return open
88	    .filter((i) => isStatus(i, STATUS_READY))
89	    .filter((i) => !open.some((o) => o.number !== i.number && titleOf(o) === titleOf(i)
90	      && running(o)))
91	    .filter((i) => {
92	      if (!standing(i)) return true;
93	      return !taskAfter(idOf(i)).some(liveUpstream);
94	    })
95	    .sort((a, b) =>
96	      (hasLabel(b, URGENT) ? 1 : 0) - (hasLabel(a, URGENT) ? 1 : 0)
97	      || draw.get(a.number) - draw.get(b.number));
98	}
99	
100	// The claim comment carries WHO and WHEN — the executor id and its run URL —
101	// because executor identity is an unbounded set and must never become a label
102	// (DESIGN §4).
103	export const claimComment = ({ executor, runUrl, at }) =>
104	  `${CLAIM_MARKER}\nClaimed by executor \`${executor}\` at ${at}.${runUrl ? `\n\nRun: ${runUrl}` : ''}`;
105	
106	// Who won the claim, out of an item's comments (DESIGN §6.2). Three precisions,
107	// each an implicit assumption made explicit:
108	//
109	//  - "EARLIEST" MEANS LOWEST COMMENT ID, never timestamp. GitHub comment
110	//    `created_at` has one-second granularity, so simultaneous claims tie on time;
111	//    comment ids are server-assigned and strictly increasing — a total order the
112	//    protocol gets for free. Nothing here compares runner clocks.
113	//  - THE ARBITER IS EPISODE-SCOPED (F18): the earliest claim SINCE the item last
114	//    became ready. Over an item's lifetime dead claims accumulate (every reclaim
115	//    and revert leaves one), and arbitrating over all of them makes a dead claim
116	//    outrank every future live claimant — the item then livelocks through reclaim
117	//    cycles forever. The reclaim / revert / re-queue comment is the boundary.
118	//  - THE LABEL SWAP IS NOT THE ARBITER, so a torn swap can never mint a second
119	//    owner; it can only leave an item with no state label, which the janitor
120	//    repairs.
121	export function claimWinner(comments = []) {
122	  const sorted = [...comments].sort((a, b) => a.id - b.id);
123	  const boundary = sorted.filter((c) => (c.body ?? '').includes(EPISODE_MARKER)).at(-1);
124	  const claims = sorted
125	    .filter((c) => (c.body ?? '').includes(CLAIM_MARKER))
126	    .filter((c) => !boundary || c.id > boundary.id);
127	  return claims[0] ?? null;
128	}
129	
130	// After WINNING a claim, re-verify the pick filters against live state (F15). The
131	// filters read possibly-stale state, so two executors can pass them simultaneously

