1	// The janitor's sweep over the WORK-ITEM QUEUE (tasks-dispatch DESIGN §11) — the
2	// half of this task that runs where `taskScheduler.dispatch` is `"queue"`.
3	//
4	// It shrinks twice over against the slot-mechanism sweep beside it. The re-arm and
5	// its grace window are GONE: an executor polls on the scheduler run's cron, so a lost label
6	// event is latency and never the only delivery. And the executing-leash reclaim
7	// moved to the SCHEDULER RUN — a deterministic label rule, serialized and hourly, which
8	// recovers a dead executor's item in ~2h instead of ~25h.
9	//
10	// What is left is everything needing judgment or a longer horizon: the dead agent
11	// claim, the stale-ready escalation, the stuck-dependency sweep (comment only —
12	// the item still proceeds by itself the moment its blockers resolve), the
13	// stateless-item repair, and a health review that can now be computed from issues.
14	//
15	// This file is the I/O shell; every verdict is a pure rule in the vendored engine,
16	// so what counts as stale, dead or stuck is decided in exactly one place.
17	
18	import {
19	  staleReadyItems, staleReadyComment, deadAgentItems, deadAgentComment,
20	  stuckBlockedItems, stuckBlockedComment, statelessItems, statelessComment,
21	  supersededItems, supersededComment, orphanedParkItems, orphanedParkComment, taskPathIndex,
22	  endedParkItems, endedParkComment, unclosedTerminalItems, unclosedTerminalComment, periodForTasks,
23	  abandonedParkItems, abandonedParkComment, scheduledForTasks,
24	} from '../../../claudinite-tasks/queue/janitor-rules.mjs';
25	import {
26	  QUEUE_LABELS, HANDOFF_MARKER, TASK_OBSOLETE, TASK_DONE, IN_REVIEW_LABEL,
27	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_FAILURE,
28	  STATUS_BLOCKED, STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT,
29	  isStatus, isParked, statusOf,
30	  parseWorkItemTitle, parseWorkItemBody, taskIdFromPath,
31	} from '../../../claudinite-tasks/queue/work-item.mjs';
32	import { listOpenWorkItems, listDoneWorkItems } from '../../../claudinite-tasks/queue/read.mjs';
33	import { lastProgressAt } from '../../../claudinite-tasks/queue/heartbeat.mjs';
34	import { ensureLabels, addLabel, removeLabel, comment, listComments, readIssue, closeIssue } from '../../../claudinite-tasks/github.mjs';
35	import { clearStatus } from '../../../claudinite-tasks/queue/apply-status.mjs';
36	
37	export async function sweepQueue(gh, repo, now, { tasks = [], log = console.log } = {}) {
38	  const open = await listOpenWorkItems(gh, repo);
39	  const result = { open: open.length, staleReady: [], deadAgents: [], stuck: [], stateless: [], superseded: [], orphaned: [], ended: [], abandoned: [], unclosed: [] };
40	
41	  // A `Blocked-by` target need not be a work item, so its state is read directly.
42	  const known = new Map(open.map((i) => [i.number, i.state]));
43	  for (const i of open) {
44	    for (const n of parseWorkItemBody(i.body).blockedBy) {
45	      if (known.has(n)) continue;
46	      const res = await gh(`/repos/${repo}/issues/${n}`);
47	      known.set(n, res.status === 200 ? res.json?.state ?? null : null);
48	    }
49	  }
50	
51	  const stale = staleReadyItems(open, now, { periodFor: periodForTasks(tasks) });
52	  // Rule B judges a beating session on its progress, which only its own comments
53	  // carry — so they are read here, for the handful of items actually holding an
54	  // agent, and handed in as a resolved lookup so the rule itself stays pure.
55	  const progress = new Map();
56	  for (const i of open.filter((i) => isStatus(i, STATUS_RUNNING_AGENT))) {
57	    progress.set(i.number, lastProgressAt(await listComments(gh, repo, i.number)));
58	  }
59	  const deadAgents = deadAgentItems(open, now, { progressAt: (i) => progress.get(i.number) ?? null });
60	  const stuck = stuckBlockedItems(open, now, { stateOf: (n) => known.get(n) ?? null });
61	  const stateless = statelessItems(open);
62	  // Rule E reads the CLOSED half of the queue, so it is the one rule with an input
63	  // the others do not share. Read once, indexed by task, newest-done-wins.
64	  const doneAfter = doneRunLookup(await listDoneWorkItems(gh, repo));
65	  const superseded = supersededItems(open, { doneAfter });
66	  const orphaned = orphanedParkItems(open, { tasks });
67	  // Rule G's input. An `Ends-when` target is a pull request or an issue in this
68	  // repo, read one at a time — there are only ever as many as there are parks
69	  // carrying the field. MERGED-NESS, not just state: the issues endpoint carries
70	  // `pull_request.merged_at` for a pull request, and it is what separates "the work
71	  // landed" from "it was abandoned". An unreadable target answers null, so the park
72	  // stands rather than ending on a read that failed.
73	  const resolutions = new Map();
74	  for (const item of open) {
75	    const { endsWhen } = parseWorkItemBody(item.body);
76	    if (endsWhen == null || resolutions.has(endsWhen)) continue;
77	    const res = await gh(`/repos/${repo}/issues/${endsWhen}`);
78	    const target = res.status === 200 ? res.json : null;
79	    resolutions.set(endsWhen, target?.state !== 'closed' ? null
80	      : (target.pull_request?.merged_at ? 'merged' : 'closed'));
81	  }
82	  const resolutionOf = (n) => resolutions.get(n) ?? null;
83	  const ended = endedParkItems(open, { resolutionOf });
84	  const abandoned = abandonedParkItems(open, now, { scheduledFor: scheduledForTasks(tasks) });
85	  const unclosed = unclosedTerminalItems(open, now);
86	
87	  if (stale.length || deadAgents.length || stateless.length) await ensureLabels(gh, repo, QUEUE_LABELS);
88	
89	  // Both labels, as everywhere: the state the machine reads plus what the human is
90	  // being asked for.
91	  const escalate = async (item, body, from, park) => {
92	    await comment(gh, repo, item.number, body);
93	    // Every spelling of the status being left goes: the item may have been filed by
94	    // an engine older than this one, and a swap that named one spelling would leave
95	    // the other standing (`apply-status`). The park that replaces it is ONE label.
96	    if (from) await clearStatus({ removeLabel }, gh, repo, item, from);
97	    await addLabel(gh, repo, item.number, park);
98	  };
99	
100	  for (const item of stale) {
101	    await escalate(item, staleReadyComment(item), STATUS_READY, NEEDS_HUMAN_ACTION);
102	    log(`escalated stale-ready #${item.number} → ${NEEDS_HUMAN_ACTION}`);
103	    result.staleReady.push(item.number);
104	  }
105	  // FAILURE, not decision: a dead session is something the machine noticed, never a
106	  // choice a person made. The kind carries two consequences that both want that
107	  // reading — it is the only park a later clean run can supersede (rule E), and the
108	  // only one that holds the task's lane, so the generator stops filing a fresh
109	  // occurrence each anchor behind a run nobody has looked at.
110	  for (const item of deadAgents) {
111	    // A beating item reached the leash because its progress stopped, not its
112	    // timeline — the comment says which, so the reader knows whether to look for a
113	    // dead session or a stuck one.
114	    await escalate(item, deadAgentComment(item, await sessionNote(gh, repo, item), { wedged: progress.get(item.number) != null }),
115	      STATUS_RUNNING_AGENT, NEEDS_HUMAN_FAILURE);
116	    log(`reclaimed a dead agent claim on #${item.number} → ${NEEDS_HUMAN_FAILURE}`);
117	    result.deadAgents.push(item.number);
118	  }
119	  for (const item of stuck) {
120	    // COMMENT ONLY, deliberately: labels untouched means the item still proceeds
121	    // by itself the moment its blockers resolve, and a human who decides it is
122	    // dead closes it by hand.
123	    const unresolved = parseWorkItemBody(item.body).blockedBy.filter((n) => known.get(n) !== 'closed');
124	    await comment(gh, repo, item.number, stuckBlockedComment(item, unresolved));
125	    log(`surfaced stuck dependency on #${item.number} (blocked by ${unresolved.map((n) => `#${n}`).join(', ')})`);
126	    result.stuck.push(item.number);
127	  }
128	  // CONFIRM BEFORE ACTING, and only here. This rule's premise is that the state it

