1	// The janitor's queue rules (tasks-dispatch DESIGN §11) — the recovery that needs
2	// judgment or a longer horizon than the scheduler run's hourly label mechanics. Each rule is
3	// pure, returning the items it claims plus the comment it would post; the
4	// janitor task's worker is the only I/O shell over them.
5	//
6	// What is NOT here: the executing-leash reclaim, which rides the scheduler run (a
7	// deterministic label rule, serialized and hourly, recovering a dead executor's
8	// item in ~2h instead of ~25h). That amends the single-recovery-site split in
9	// siting, not in principle — recovery still happens once, in one place per rule,
10	// in code, and never as a sweep inside a session that is executing something.
11	
12	import { periodMs } from './anchors.mjs';
13	import {
14	  READY, AGENT, requeueHint,
15	  STATUS_READY, STATUS_RUNNING_AGENT, STATUS_BLOCKED, STATUS_DONE, STATUS_REJECTED, isStatus, statusOf,
16	  isParked, parkKindOf, originOf, ORIGIN_AD_HOC,
17	  parseWorkItemTitle, parseWorkItemBody, taskIdFromPath,
18	} from './work-item.mjs';
19	
20	export const AGENT_LEASH_MS = 3 * 3600e3;
21	// The park kinds a later clean run ANSWERS. Both name a broken thing — a failure is
22	// "read the trace", an action is "the token is missing" — so a run that converged
23	// clean is proof it is not broken any more. `approval` and `decision` are absent on
24	// purpose: those parks carry content a person still owes an answer to (an approval
25	// park typically holds an open PR), and a later success does not answer them. What
26	// DOES answer an approval park is that pull request resolving — rule G.
27	export const SUPERSEDABLE_PARKS = Object.freeze(['failure', 'action']);
28	export const STALE_READY_PERIODS = 2;
29	// How long a terminal status may stand on an open issue before rule H reads it as
30	// torn rather than in flight. A converge writes the label and the close within
31	// seconds of each other, so an hour is far past any live transition.
32	export const TERMINAL_OPEN_MS = 3600e3;
33	export const STUCK_BLOCKED_MS = 2 * 86400e3;
34	
35	const ms = (t) => (t == null ? null : new Date(t).getTime());
36	const idle = (item, now) => ms(now) - (ms(item.updated_at) ?? ms(item.created_at) ?? ms(now));
37	
38	// Rule A — STALE READY. An item no executor picked for ~2 of its own periods comes
39	// out of the queue as a human's problem. The period is read from the task's
40	// declared `frequency` at HEAD (no title parsing — that was the slot grammar); an
41	// item whose task is unknown falls back to a day.
42	//
43	// WHICH TASK, on a marked issue: its title is the person's own, so the id comes
44	// from the worker path its machine block names — without that fallback a request
45	// nobody picks up would sit ready forever, the one item class no rule here covers.
46	export function staleReadyItems(open = [], now, { periodFor = () => null, factor = STALE_READY_PERIODS } = {}) {
